    "summary": "一份拆到操作层的 AI 短片教程：开拍前先建资产库、给每份参考图只派一个任务、用统一命名让 Claude 和生成工具对得上，再逐项补材质。",
    "takeaway": "**这条把我们这几天零散摸到的规律，全部落成了可执行的制度。** 核心问题写得极准：**“单个镜头看着不错，接起来却像几部不同的电影：人物换了脸，办公室换了布局，上一镜的动作到了下一镜接不上。”** 三条做法值得直接抄：①**每份参考只派一个任务**——**“人物视频提供身份和表演，场景图片提供空间，道具图片提供外形。不要让一张图同时负责脸、服装、动作和机位。”** ②**统一命名是跨工具协作的基础**——角色用 `@char_adam_video_v1`，地点用 `@loc_alley_v1` 这类名字，Claude 里写的名字与生成工具里绑定的名字保持一致；**“这些名称的价值在于对应关系。提示词写到哪个人物、哪个房间，就能找到那份已确认的素材。”** ③**把“更真实”拆成可以看见的材质目标**——角色定妆后，分别提供**头发、皮肤、背景、T 恤面料**四张参考图，按顺序挂上去（@image_1 已确认的角色设定图、@image_2 头发、@image_3 皮肤、@image_4 背景、@image_5 面料），作者原话：**“Each reference has one job, so the model gets a concrete visual target.”** 它还配了四份可下载的 Skill，分工很清晰：提示词组织、打斗动作关系、情绪表演与对白、变形宽银幕视觉语言。**这三条其实是我们已经采过的三期拼在一起**：第 130 期“统一在人设和场景资产库里”、第 160 期“用手掌当比例尺”、第 164 期“给规则加边界”——**这里把它们写成了一套可以交给团队执行的制度**。**注意**：①原作者用的是 Higgsfield + Seedream 5.0 Pro + Claude 的组合，**换工具要重新验证**；②文中自己指出一处瑕疵——**说明里的上传顺序与内嵌提示词的图片编号并不完全一致**，实操时要以提示词编号为准；③这是二手整理，**原教程和附件在原文链接里**，我们没逐一下载核对。",
