    "takeaway": "**这是目前见过的、把“规则写死”写得最漂亮的一条提示词，值得当模板拆。** 三个可直接借的方法：①**给能力加边界，不加形容词**——五条超能力每一条都写了极限：“金属操控**仅能**移动或变形已存在的金属物体，**变形后保持状态**”；“动能吸收**仅能**通过两次格挡充能，**一次掌击释放**，伴随短暂金色闪光”；“局部时间能力**仅能**减缓路径上的空中玻璃”；“影子转移**仅能从 A 影消失、从 B 影出现**”；“个人重力**仅能在一次外部恢复时降低体重，落地后恢复正常**”。**“仅能”这两个字是全篇的命门**——它把“随便发挥”变成了“按规则解题”，也顺手堵死了模型乱加戏的空间。②**时间线精确到半秒**：从 00:00-00:03 破窗进入，一路写到 **00:23.5-00:25**——**全片唯一的电影慢动作，猎人的拳头擦过她的脸颊**，再到 00:27-00:30 滑门关闭、说出**全片唯一一句台词“End of the line.”**。注意它连“唯一”都规定了：**只有一个慢动作镜头、只有一句台词**。③**音效独立成段、逐项列清**：车轮节奏、列车震动、风声、脚步声、呼吸声、衣物摩擦、装甲伺服声，**“仅在慢动作段落拉伸整体音效，无额外音乐、旁白或字幕”**。**这套写法对我们最有用的一点是：把“我要什么感觉”换成了“什么情况下会发生什么”**，和第 126 期（数字指令要换成可见参照物）、第 160 期（给道具一个手掌当比例尺）是同一条脉络。**注意**：这是一条 X 上流传的作品，**没有第三方复现，也没有给出完整提示词原文**（AI Pulse 是转述与摘录）；“看起来像 John Wick 和影子打了一架”是作者自评，别当评价依据。",
