    "summary": "九旬老人连发蔚捐出两张存了 70 多年的照片——1952 年，一位女战士把四五岁的女儿托付给她，留下一张写着“送给妈妈”的小女孩照和一张自己写着“云涛的妈妈”的戎装照。",
    "takeaway": "**这条有一个镜头，是那种一辈子只能遇到一次的镜头。** 连发蔚回忆当年送那位女战士出门：**“我就牵着云涛到门口送她。她走了一段，回头看看她的孩子，走了一段，又回头看看她的孩子……”** 讲到这里老人呜咽了，把眼睛埋在臂弯里，手里紧紧攥着两张旧照片。**就这一句，就是一部短片。** 托付那句也是原话：**“如果我牺牲在朝鲜战场，希望女儿大一点的时候能知道，照片中的人就是她的妈妈。”** 两张照片的题字构成了全部叙事：一张是小女孩云涛，上面写着**“送给妈妈”**；另一张是女战士的半身戎装照（像是从合影上剪裁下来的），背面是**“送给发蔚同志留念，云涛的妈妈”**。那年连发蔚才 15 岁，在河北邢台的留守处幼儿园看护 100 多名志愿军的孩子；1953 年一纸调令把她调去旅顺口，她连跟云涛道别都没来得及。**这两张照片后来被收在锦盒里，跟着她从河北到辽宁，又从辽宁到四川，贴身带了 70 多年。** 拍法建议：**全片不必出现战争，只要一只手、一个锦盒、两张照片和那一句“回头看看她的孩子”**；结尾停在 11 月 10 日纪念馆发布“寻找云涛”的那条信息上。**注意**：云涛的身份、那位女战士的下落**至今都没有确认**，文中线索“来了，断了，又来了，又断了”——片子**绝不能替她补一个结局**，也不要把未核实的信息写成事实。老人已是虚岁九十，引用原话需注明出自纪念馆口述史料采集。",
