    "summary": "Phai-M1 的能力参数补齐了：单段 5–20 秒、三档清晰度，对白、音效与环境声随画面一起生成，一张 16GB 消费级显卡渲 15 秒 720p 约 3 分钟。",
    "takeaway": "**这是对第 124 期的参数补全，而且今天就能上手试。** 关键数字：**支持 5–20 秒的单段视频**，清晰度 480p / 720p / 1080p 三档；**对白、音效和环境声随画面一起生成**（124 期只知道“支持音画同步”，现在有了范围和口径）；**官方测试用一张 16GB 显存的消费级显卡，生成 15 秒 720p 约需 3 分钟**。**四种生成方式值得对照我们的流程看**：文生视频、图生视频、**首尾帧过渡**（首尾帧都上传后，模型生成两图之间的过渡，**提示词可以留空**）、**参考生成**（最多两张人物或主体图，**各可配一段参考声音**，另可加一张背景图）。最后这一条是重点——**它把“外观、声音、场景”拆成三路输入**，这正是做人物短片最需要的（也呼应第 160 期那条“用手掌当比例尺”的思路：给参照物，别给形容词）。画幅支持 16:9、9:16、4:3、3:4、1:1。**用得上的两点提醒**：①文中说首尾帧控制**主要用于单个镜头**，要做连续剪接的短剧，仍需先用分镜工具排好相邻镜头的景别与顺序，再逐个准备首尾帧素材；②**权重“即将发布”**——Hugging Face 与 ModelScope 都只标了即将发布，**所谓“开源”目前还没兑现**，别当已开源写进方案。",
