    "title": "【常言道】更要扣爸爸的分",
    "source": "常州网博客（cz001.com.cn）2026-11-20 09:19，作者柏文学；“常言道”评论专栏",
    "url": "https://blog.cz001.com.cn/index.php?c=Wap&m=detail&id=193800&s=wap_normal",
    "heat": "只有讨论度，无数字（博客页面显示“24 1 0”与 1 条评论，但页面未标明这三个数字各指什么，我们不臆测；文中称该题“在杭州一个家长群乃至全网引发热议”，这是作者转述，**我们没查到原始帖子或热搜记录**）",
    "summary": "一道三年级语文扣分题在家长群引发争议：妈妈要打包剩菜、爸爸觉得没面子，孩子的答案是“不打包，我们也不差这几块钱”，被扣 4 分；孩子爸爸把试卷发上网，问“实话实说为什么不对”。",
    "takeaway": "**这是这几天采到的最适合拍的一道德育题，因为它自带三人场景、一句台词和一次反转。** 题目原文：**“小明和爸爸妈妈一起到饭店吃饭。饭后，小明的妈妈要把剩下的饭菜打包，爸爸觉得这样做没面子。如果你是小明，会怎么做、怎么说？”** 学生的答案：**“如果我是小明，我会告诉妈妈不用打包，我们也不差这几块钱，而且这样做被别人看到还很丢脸。”** 老师扣 4 分。**最狠的一层是后续：孩子按要求订正了，但心里不服，因为“答案是他心里的真实想法，订正的内容却不是”。** 然后是爸爸把试卷发到家长群、传到网上，公开质疑——而作者的回击比扣分更锋利：**“我认为，更该扣分的是这位家长。学生只是为爸爸背了锅。”** 这篇还给了三句可以当台词的话：**“实话实说的行为方式，当然是正确的；但是实话实说的内容，不等于一定正确。”**／**“爱惜粮食资源，才叫‘有面子’；浪费粮食资源，恰恰正是‘很丢脸’‘没面子’的事。”**／**“不让孩子替爸爸的‘丢人’找理由，让孩子理直气壮地站在妈妈一边。”** 片中最好的一镜其实不用演：**孩子在试卷上把“真实想法”划掉，旁边写上标准答案**——那一笔就是全片。**注意**：这是个人博客评论，观点只代表作者；**题目原件、学校、扣分细节我们都无法核实**，片子里不能指认具体学校或个人。另外价值判断请保持一分为二：浪费粮食确实不对，但“孩子被迫写一个自己不信的答案”这个困境也真实存在——片子可以把两个困境都摆出来，不要替观众下结论。",
