    "title": "7 个要素讲透 AI 短剧分镜：景别、角度、构图、光影、色调、动势、转场",
    "source": "火星时代教育 2026-07-06，作者“奋努的小枫”",
    "url": "https://www.hxsd.com/content/59450/",
    "heat": "页面显示浏览量 268（无评论数）；这是培训机构的教学文章，不是行业测评",
    "summary": "把 AI 分镜拆成七个可写进提示词的要素，最后给出一句包含景别、角度、光影、色调、动作的完整范例，并强调七者要组合使用。",
    "takeaway": "**这份东西可以直接给分镜老师当检查表用，因为每个要素都落到了“提示词怎么写”。** 最实用的是六个“实操要点”：①**景别要有节奏**——冲突爆发前用中近景铺垫，爆发瞬间切特写冲击，高潮过后拉远景释放情绪，**“全程一个景别，跟读 PPT 没区别”**；②**角度本身就是叙事**——**“角色受辱时俯视压低，角色觉醒反击时仰视抬高”**；③**构图别堆**——同时写“三分法＋对称构图＋引导线”，**AI 会算力分散，画面反而崩**，选一种主构图写清楚；④**光影必须写“类型＋光源方向”**——“不写光影的提示词，出图就像手机闪光灯直拍，亮是亮了，没质感”；⑤**色调单集只用一种主色调**，而**系列短剧可以用色调演变暗示剧情走向——前期冷调压抑、后期暖调治愈，“这种变化本身就是叙事”**；⑥**动势要写“运动类型＋运动速度”**——“推镜头”不够，要写“缓慢靠近”还是“快速逼近”，另外硬切加静止镜头往往比全程花式运镜好看。**它给的完整范例可以直接抄格式**：**“特写，微仰视角度，逆光轮廓光，暖色调，女主摘下黑框眼镜的瞬间，眼神从隐忍转为凌厉”**——一句话里塞进景别、角度、光影、色调、动作五项。文末一组数据也值得记：**AI 短剧制作成本已降到真人短剧的 1/10，但投流成本同比涨超 100%，千次播放收益从 60 元腰斩到 15–30 元。** **注意**：文章发布于 2026-07-06，不是今日新发；作者是培训机构的运营号，文中“每天超过 1300 部 AI 短剧上线、每 1000 部只有 1 部能跑出来”没有给出处，**当参考不当依据**。",
    "status": "备选",
