    "time": "08:42",
    "title": "6 种立刻能上手的实拍×AI 结合方式丨AI 工坊笔记①",
    "source": "川观新闻 2026-11-09 16:43，记者高永虹、葛仙雅；主讲超级创作者 @庄旭，属“万千气象 AI 创作工坊”第 1 讲",
    "url": "https://cbgc.scol.com.cn/news/8114121",
    "heat": "页面显示“精彩评论 9”（不显示阅读量）。同系列第②讲（第 144 期）、第⑤讲（第 114 期）均已采",
    "summary": "把实拍与 AI 结合拆成六种立刻能用的具体操作：改元素、换风格、重打光、补机位、换背景、改人像，每种都给了提示词范例。",
    "takeaway": "**这是目前我们采到的最“能直接上手”的一条，六种方式每种都配了提示词原句**：①**元素修改**——“请把视频中主角的休闲外套换成西装”（路人多余、发型不对同理）；②**风格转换**——“请把视频 1:00-1:05 的片段换成水墨风格”，作者提示这个最适合**创意提案阶段**用，先让客户看到效果片段再谈；③**光影重塑，作者自己标注为“最实用”**——“请将视频的天气设定为晴天并调整相应的视频画面”，理由是**实拍的本质是玩光，户外踩到坏天气不用重拍**；④**补机位**——“请生成一段俯拍机位的视频片段”，三个机位回来发现漏了一个就靠这个；⑤**改变背景**——“请将此段视频中的海岸背景改为森林背景”，**但作者明确划了红线：创意、补拍、场景重建可以，新闻纪实里不行**；⑥**人像编辑**——换发色、调表情、改情绪、美颜。**全文最有价值的是结尾那段判断**：过去我们用“数手指、找文字、看畸变”分辨 AI，这些方法**已基本失效**；现在最有效的破绽恰恰是**“过于完美”**——AI 画面干净、对称、没噪点，反而显得假。**“创作者做内容时，适度保留噪点与不完美，反而更真实、更有‘活人感’。”** 这对我们是直接可用的：做家庭教育片不必追求假高清，**留一点手持、一点环境噪、一点不完美，反而更像真的**。**注意**：这是培训课程的图文笔记，不是独立测评；“补机位”“改背景”这类操作在成片里滥用会被观众看出，**边界那条红线（纪实类不能用）必须守住**。",
    "status": "备选",
