    "title": "那个说“我一点都不想来”的孩子，五天后说“我的心能静下来了”",
    "source": "搜狐号“业务姐在线教学”2026-11-18 22:55（心理咨询师自述随笔）；其一手的新闻来源为腾讯新闻 11-18 关于云南宾川“心田大理”项目点的报道，以及同日人民网关于“家庭教育没有特效药”的锐评与暗访报道",
    "url": "https://www.sohu.com/a/1103352079_121124335",
    "heat": "只有讨论度，无数字（搜狐页面不显示阅读与评论数）。可核的引用：文中提到的腾讯新闻 11-18 报道（云南宾川金牛镇、6 组初中生家庭、大理州强制隔离戒毒所戒毒康复专区、五天课程、签署《家庭成长行为契约》）我们**没有直接打开核实**，属二次引用；人民网同日两篇锐评可另查",
    "summary": "云南一个项目把 6 组初中生家庭带进戒毒所的院子待了五天：孩子从“我一点都不想来”，到第五天说“我的心能静下来了”——全程没有一句是“教育”。",
    "takeaway": "**最有画面的一个细节不在新闻里，在咨询室：** 十四岁的男孩坐在沙发角上，两只手插在校服口袋，**肩膀往里收，像想把自己叠得更小一点**。妈妈说了快十分钟，老师说“你先别说了”——后面大半小时三个人几乎没讲话，快走时那孩子抬头看了妈妈一眼，**那是半年里她第一次被孩子主动看**。作者由此给了一句可以当全片落点的判断：**“肩膀是有记忆的——一个孩子在谁面前能把肩膀放下来，说明他信谁。”** 另一处同样好拍：一位爸爸给休学的儿子列了密密麻麻的表（几点叫起床、几点收手机、几点谈一次心），作者只问他有没有哪天什么都不做、就陪他坐一会儿，他说没有，**“我怕我一停下来，他就彻底废了”**；后来让他划掉“每天谈一次心”这一项，三个星期后，儿子晚上自己出来倒水，站着说了几句——**“我们拼命做的那些事，有时候恰恰是把孩子推开的那只手。”** 项目本身的结构也可以直接用：课程顺序是**适应接纳→建立规则→重塑价值→明晰法治，最后才回归家庭**；收尾时家长和孩子**一起签一份《家庭成长行为契约》**，把情绪怎么处理、出勤、手机、奖惩一条条写下来——**通篇没有一句“你要听话”，写的都是具体的事**。给短片一句台词：**“不急着让他变好，本身就是一种很深的相信。”** **提醒**：“心田大理”的细节全部转自腾讯新闻，我们**没打开原文核实**，引用前必须回源；作者是心理咨询师、这是个人随笔，不构成诊断。文中另提一个可核事实：**2017 年之后心理咨询师证已不是准入类执业证书**，可用于提醒别买直播间的课。",
