    "title": "做了 6 年自媒体，公开我的 AI 视频创作流程！【独家】",
    "source": "腾讯云开发者社区 2026-11-16 18:33，作者“程序员鱼皮”（B 站 UP 主，全网粉丝 200 多万，开源作品含 ai-promo-video-maker、yupi-skill）",
    "url": "https://cloud.tencent.com.cn/developer/article/2785714",
    "heat": "页面显示阅读 4700（真实数字，非营销口径）",
    "summary": "一位做了六年视频的 UP 主把整套 AI 视频流程公开：先把口播稿和素材人工粗剪再交给 AI，用逐字时间戳精确剪掉重录，用 HTML 写画面再渲染成视频。",
    "takeaway": "**这份流程里有四条可以直接搬进我们产线。** ①**先图文后视频**：图文是一次低成本的试水，一个选题图文没人看，做成视频大概率也不行。②**视频稿不能照搬图文**——他给了同一内容的两个开头做对比，图文版是“今年国庆假期，别人都出去旅游嗨皮了……”，视频版改成**“这是我第一次做面向全球的出海产品，近 7 天已经有近 5 万的浏览量了，猜猜我盈利了多少？”** 结论就是**结论先行、成果先行，第一句话把人抓住**。③**人工粗剪不能省**：原始素材里有废片和重录，全丢给 AI 既烧 tokens 又容易在无效内容上反复折腾，人顺手剪一遍反而更快。④**逐字时间戳是关键**：用语音转写服务把口播转成带每个字时间点的文本，AI 才能精确剪掉重录、取每句话最后一遍说完整的版本，剪完再转写一遍逐段比对，“少一个字都能发现”。**画面侧有个思路很妙**：用 HyperFrames 让 AI 写 HTML/CSS/GSAP 再渲染成视频——**写网页是 AI 最擅长的事之一**，所以出错少；他实测 5 分多钟的 4K 科普视频渲染只要 8–12 分钟，而用 Remotion 要 30 多分钟（注意 Remotion 对 4 人及以上公司需购买授权）。**还有两条原则值得记**：**“真实素材永远是主角”**——讲产品放真实截图，讲工具放真实录屏，AI 生成的画面只负责包装和转场；以及**AI 听不到声音**，所以配乐好不好听、音色搭不搭必须人耳过一遍，AI 只能把旁白转写成文字逐句比对。文中还提到配乐可用 Mixkit 这类免费可商用曲库，让 AI 分析节拍把镜头切换卡在鼓点上。**注意**：这是个人博主的工作流，面向知识科普类口播视频，**和我们的叙事短片不是一个类型**，他的自动化程度（AI 全剪）不适用于剧情片；作者也自述“这套方法不一定是最好的”。",
    "status": "备选",
