    "summary": "中国教育报报道的一场校家社协同育人论坛上，张志勇提出“十五五”期间协同育人的三大任务，重庆渝中区则披露了“15 分钟校家社协同育人服务圈”的做法。",
    "takeaway": "**这条是背景资料，不是故事，但它给了两个值得记住的表述。** 一是全国政协委员、北师大教育国情调查中心主任张志勇对“十五五”任务的概括：**“全面提高家庭教育素养、全面呵护儿童健康成长、全面加强社会实践教育”**，并强调家庭教育、社会教育、网络教育的重要性——如果客户问政策方向，这是官方口径。二是重庆市渝中区教委总督学周竹分享的实践：全域构建“教联体”、打造**“15 分钟校家社协同育人服务圈”**，这是个能给画面感的概念，可以想象成一张以家为圆心、走路十五分钟能覆盖的地图。另有一个学术表述很锋利：北师大教育学部副部长余清臣讲**“现代学校教育系统对家庭的‘吸纳—嵌入’机制及其治理”**——**学校系统把家庭“吸纳”进去**，这个命名正好接上第 123 期那条“家长负担”的现象，一个讲机制、一个讲后果，可以放在一起看。**提醒**：这是会议通稿，通篇没有人物、没有故事、没有具体案例，**不能直接做成片子**，只能当剧本老师的背景资料用；且论坛发言多为政策与学术表述，引用时请注明“在论坛发言中提出”，不要说成正式文件。",
