    "title": "父母在，爱就在",
    "source": "《河源日报》2026-11-19 第 07 版“万绿湖”副刊，作者纪学梅",
    "url": "https://epaper.hyrbnews.cn/html/2026-11/19/content_94923_4028975.htm",
