    "period": 141,
    "date": "2026-11-20",
    "time": "01:42",
    "title": "孩子“拒学”后，父母在漫长自愈",
    "source": "中国青年报（记者焦晶娴），河北省关心下一代工作委员会春泥网 2026-11-18 10:54 转载；受访者为首都医科大学附属北京儿童医院“拒学门诊”医生李瑛，及其著作《接住孩子：6000 个小时的心身诊疗手记》",
    "url": "http://chunni.org.cn/jkgw/58500.html",
    "heat": "只有讨论度，无数字（春泥网转载页显示点击 18 次；中国青年报原版面的阅读数据我们没查到）",
    "summary": "北京儿童医院的“拒学门诊”开了两年多，医生发现：孩子不上学，父母先垮——有家长因此犯高血压、查出甲状腺囊肿，有人上午给孩子看病，下午给自己看病。",
    "takeaway": "**这是今天采到的最重的一条，母题我们库里没有：孩子拒学，父母先病。** 最有画面的一个细节是一位母亲——职场上原本前途光明，晋升关键期怀孕辞职，**每天早上准备三种早餐、认真挑选孩子出门的衣服**，然后突然有一天，孩子说不想上学了。这一组对照本身就够一支短片，不需要任何解释。李瑛那句判断是全篇的钥匙：**“家长的崩溃，是因为无法接受一种深刻的丧失——关于期待、想象，以及那个我们曾以为会平稳展开的未来。”** 他把这种丧失感比作**“十级的宫缩剧痛”**。父母会经历几乎相同的四步：**否认**（“这不可能发生在我孩子身上”）→**愤怒**（“我都为你做了这么多，你怎么还这样”）→**讨价还价**（“我是不是还漏了什么”）→**绝望**（“我管不了了”）。还有两句可以直接当台词：**“母亲焦虑的根源各不相同，父亲不在场的方式各有理由”**；**“拒学只是他们自救的手段”**——孩子过早承担了维持家庭系统稳定的压力，升入初中叠加学业压力，到了极限才用不去上学来自保。李瑛给家长的建议里有一个特别适合做成片中转折的：**“为自己花一笔钱”**——独自去爬一次山，或者做一次美甲，因为**“这种平复的过程，就是对孩子最生动的情绪教育”**。还有一个能当全片落点的示范，讲怎么真诚地欣赏孩子：孩子照顾小猫时，从前的说法是“你终于开始懂事了”，后来换成**“它那么怕水，总是乱动，你却能那么耐心地安抚它。它有没有不小心抓到你？”** **医学红线必须标死**：文中提到有孩子手腕带新鲜划痕、皮肤上有指甲掐出的红痕，这些都属临床范畴，片子里绝不能呈现自伤细节或给任何判断；结尾也不要用“复学”当作解决方案——李瑛的原话是**“复学只是帮助孩子康复的手段，而非人生最终的意义”**。",
    "status": "备选",
