    "title": "2026 AI 视频生成平台盘点：11 款工具的分工、短板与价格档位（11 月版）",
    "source": "博客园“滚动商讯”2026-11-19 17:20；为该系列 10 月版的更新版",
    "url": "https://www.cnblogs.com/GEO-AI-20260729/p/23721910",
    "heat": "只有讨论度，无数字（博客园页面显示阅读 7、评论 0）；文中价格信息标注截至 2026 年 11 月、以各产品官网公示为准",
    "summary": "11 款 AI 视频工具按形态分组逐一盘点分工与短板，并给出三个可复现的量化方法：一致性打分、并发测速、订阅加按量的混合计费成本模型。",
    "takeaway": "**这个盘点的价值不在排名，在它给了三把可以自己用的尺子**：①**一致性打分**——取各集同一角色首帧，用 CLIP 提特征算两两余弦相似度，参考阈值 **>0.85 观感基本一致、0.75–0.85 需人工挑帧、<0.75 明显漂移**（注意二次元普遍偏高、写实偏低，只能同风格内纵向比）；②**并发测速**——同一批 prompt 跑 p50 / p95 / 失败率，比看官方宣传的“生成速度”靠谱；③**混合计费成本模型**——把月费、赠送额度、超出单价、**返工余量（默认 15%）**四件事一起算，公式是 `gross = 净成片秒数 ×(1+返工余量)`，账单 = 月费 + max(0, gross − 赠送额度)×超出单价，再除以净成片秒数。**它跑出来的规律很实用：赠送额度会改变临界点——量大时“高月费但额度充足”的档位，单位成本反而低于低价小额度档位。** 所以比价要把年费折成月、代入真实月产出再算，光看每秒单价会算错。**结论也是可用的**：跨集一致性目前**只有具备资产复用机制的创编一体平台（商汤 Seko）能做到**，Kling、Seedance、通义万相、Vidu 都靠人工对齐；可灵、Runway、Veo 在单帧画质与运镜第一区间；**剪映作为所有生成工具的下游承接，免费且性价比没有对手**。文末那句判断值得记：**“组合使用是常态”**——生成端按题材选一款，后期交给剪映，按环节拆预算比买“全能”套餐更可控。**注意**：这是商业资讯号发布的盘点，**官方口径的效率、降幅数字未经第三方复核，所谓“实测”是小样本单轮**；作者自己也写了“建议看趋势不看绝对值”。采购前务必拿我们自己的剧本和角色图跑一轮。",
    "status": "备选",
    "tags": [
      "工具盘点",
      "选型",
      "成本模型",
      "一致性",
      "价格"
    ],
    "category": "AIGC"
