    "title": "当一家 AI 大模型公司走进电影节，它想解决什么？",
    "source": "毒眸（搜狐号）2026-11-19 14:53；主角为智象元一 HiDream，在金鸡电影节最后一天发布帧赞 2.0 与原生全模态视频模型 HiDream-O1-Video-1.1",
    "url": "https://www.sohu.com/a/1103619658_100240657",
    "heat": "只有讨论度，无数字（搜狐页面不显示阅读与评论数）。文中可核事实：发布会在金鸡电影节最后一天举行，与国贸资本、上影股份共同发起“新电影创作支持计划”，首轮推介 18 部作品",
    "summary": "HiDream 在金鸡发布面向专业影视团队的帧赞 2.0：用“创意画布＋分镜画布”双画布对应导演与各部门协作，把绿幕替换、场景拓展、特效增强沉淀成可复用 Skill，并用两个真实电影项目演示 AI 怎么进片场。",
    "takeaway": "**这篇正好对上我们“剧本老师＋分镜老师”的分工**：帧赞 2.0 的核心是**双画布**——导演在“创意画布”里交互式推演视觉方案，再在“分镜画布”里把方案落成具体镜头，摄影、美术、视效围绕同一套方案协作。也就是说，行业内已经把“构思”和“分镜”当成两个可以分开、又可以共用的图层来做。**第二个可抄的是“实拍＋AI”沉淀成可复用 Skill**（绿幕替换、场景拓展、特效增强）。**最值得记的一句话是梅涛那句：“物理规律是整个电影叙事感的底层密码。”** 他给了两个检验镜头：风衣怎么随风摆动（气流、布料、重量）、眼泪怎么从脸颊滑落（重力、表面张力、皮肤摩擦）。文中做了一个同提示词对比，核心提示词是：**“0–3 秒时，女性下眼睑外侧的泪水缓慢积聚；7–12 秒时，女性头部缓缓向一侧倾斜约 15 度，而摄影机始终保持固定，不随人物动作旋转。”** 他点破了小屏和大屏的分野：**小屏有“速食”属性，观众宽容；上了大屏，“经不起推敲的动作细节、光影方向都会成为被舍弃的理由”。** 还有一条成本思路可以直接用：导演陈筠两年前想在一艘船里下一场黑雨没拍成，两年后**把历史老照片导入工具生成水上场景的空间白模**，先推敲船只停靠与人物路线，再局部搭景、远处用 AI 延展——**该搭的搭、该生成的生成，钱花在刀刃上**。制片人沈洋举《河边的错误》的例子说得更直白：先判断这个表达在银幕上成不成立，再花钱搭景。**注意**：这是厂商发布会报道，对比测试是厂商自测，没有第三方复现；“即将发布的下一代世界模型”也未上线，不要当现有能力写进方案。",
    "status": "备选",
