    "title": "长征主题系列 AI 微电影《星火映征途》发布",
    "source": "新华社北京 2026-11-19 电（新华网 22:42 发布）；首映式暨京西剧谷×京西智映 AI 共创计划发布会 11 月 18 日下午在门头沟 XR 沉浸视听联合实验室举行；联合出品方为新华社解放军分社、新华出版社、京西智映人工智能影视创新中心",
