    "summary": "河北一位妈妈辅导哥哥写作业时情绪失控、反复喊“我都跟你讲了一百多遍了”，一旁的妹妹悄悄躲到桌子底下，缩成一团，不敢发出声音。",
    "takeaway": "**这一条最好的不是妈妈发火，是沙发后面那一小块地板。** 画面本身已经是完整的：妈妈和哥哥在桌上，妹妹在桌下，**一张桌子把家分成两个世界**——镜头反而不必给妈妈的脸，只给桌子底下那双眼睛。那句“我都跟你讲了一百多遍了”几乎是全国家庭的通用台词，可以直接用。而真正把这条抬起来的是评论区那句解读：**“妹妹害怕的不仅是此刻发火的妈妈，更是将来可能同样严厉辅导自己作业的妈妈。”** 这一句把“二胎旁观者”这个我们库里没有的视角点出来了——她怕的是**还没发生的事**。建议和另外两期串成“作业现场”系列：第 125 期（磨蹭是孩子唯一能掌控的东西）、第 129 期（孩子的内心像被塞满的垃圾桶），三期的场景完全一样，视角各不相同。**引用提醒**：这是一条短视频新闻，除上述这一处细节外没有更多可核信息，孩子的姓名年龄、家庭具体情况都没披露，做片子只能当“典型场景”用，不要指名到具体人。",
