    "title": "《万妖》进影院，红果布局电视端，AI 视频的下一站是大屏？",
    "source": "界面新闻“AI 价值官”（文｜星野，编辑｜美圻），新浪财经网易号 2026-11-19 13:12 转载",
    "url": "https://www.163.com/dy/article/LC3NSG3K05568W0A.html",
    "heat": "只有讨论度，无数字（网易号页面显示 0 跟贴）。但文中援引的第三方数据可核：QuestMobile 2026 年 9 月红果免费短剧月活 4.3 亿、同比 +81.8%，红果免费漫剧月活 7883 万；2026 年 6 月全国智能电视活跃设备 3.02 亿台；前三季度内地电影总票房 295.81 亿元、同比下降 29.5%",
    "summary": "AI 内容开始往大屏走——《万妖图录传》109 分钟特别篇进影院、红果招 OTT 产品经理做电视端、Seedance 2.5 4K 的 30 秒宣传片上了 20 多家高端影院，三件事挤在四天里。",
    "takeaway": "三件事几乎同时发生：**11 月 16 日**火山引擎全面开放 Seedance 2.5 4K 的 API，宣传片进北京上海等 20 多家高端影院；**11 月 17 日**红果挂出 OTT 端产品经理岗位，从 0 到 1 建电视端，招聘里明确写了 OTT 牌照申请、内容送审和审核结果回传；**11 月 20 日**《万妖图录传》特别篇《云州异客》进影院。**最值得抄的是它的发行方式**：109 分钟，走中影预约放映进全国 200 余座城市，观众先选城市场次、凑够人数才确认开场——杭州票价 30 元，截至 11 月 17 日已 7 场成团；成本据业内测算几百万元，票房过千万元即可回本，按 30 元票价约需 33 万人次，摊到 200 余城每城约 1600 人。**这是“先有粉丝再开场次”，跟一个月前先排片再找观众的 AI 院线长片《三星堆：未来往事》正好相反，而后者市场反响平平——“有证”不等于“有观众”。** 对我们的三条提醒：①**分辨率一高，AI 的毛病更难藏**，人物面部、服装细节、场景纹理看得越清楚，生成问题越明显，这正是第 130 期“60 分也算废卡”的另一面；②手机上一集一两分钟、可以倍速划走，**大屏要求完整的故事结构和情绪节奏**，这是短视频团队最容易低估的门槛；③**合规是硬门槛**——9 月 1 日起《微短剧发展管理办法》施行，互联网电视、IPTV、有线电视都被纳入监管。另可记一个行业比例：今年 5 月 AI 短剧首次占据每日 TOP100 半数以上席位，8 月已升至约七成；仅 7 月抖音端新上线 AI 剧就有 74313 部，占当月新上线短剧的 75.4%。",
