    "summary": "丈夫离世、长子猝逝，69 岁的母亲找了幼子 33 年——而两人现在的住处相距不足 3 公里，可能已经无数次擦肩而过。",
    "takeaway": "这条的全部力量都在一句话里：**“相距不足 3 公里”**。它比任何煽情都狠——不是找不到，是**这些年一直在彼此三公里之内**。结构也现成：**33 年 与 3 公里 的对撞**。可以做成一条路的一镜到底——母亲每天走的那条街，镜头慢慢拉开，儿子就住在隔壁那个小区。三重失去（丈夫、长子、幼子）叠在一起，但片子里**不必全说**，只说“她还在找”，把“3 公里”留到最后一句字幕。**风险必须写清**：这条只有一段说明文字加 10 秒视频，除“69 岁、33 年、相距不足 3 公里、丈夫离世、长子猝逝”之外**没有任何其他可核细节**——孩子当年怎么走失、如今是否已经相认、后续进展，我们都没查到。做片子只能用这几个已确认的事实，**不要补情节**。另外视频素材版权属封面新闻，使用要授权。",
