    "title": "AI 视频，进入 DeepSeek 时刻？",
    "source": "36 氪 2026-11-19 19:39，转载自微信公众号“AIX 财经”，作者王璐",
    "url": "https://eu.36kr.com/zh/p/4076581131244674",
    "heat": "只有讨论度，无数字（36 氪页面不显示阅读量）。但文中可核数据密度很高：Gemini Omni 1.2 Flash 720p 定价 0.07 美元/秒、可灵 2026 上半年收入超 15 亿元、火山引擎 MaaS 目标 150 亿元等，均标注了出处或转述来源",
    "summary": "模型能力差距在收窄、价格被打到分/秒、创作者开始批量调用；但到目前还没有一家 AI 视频模型公司公开实现盈利。",
    "takeaway": "**对选型最有用的是一条**：Arena 视频榜用 Elo 盲测，第一名领先第七名只有 65 分，国产的 Wan 3.0、Seedance 2.5、MiniMax H3 差距集中在 20 分以内，“统计上几乎并列”。多位创作者的反馈一致：同一类镜头可灵和 Seedance 都能出，切换时主要看价格、速度和接入顺不顺手。**结论是我们不该再纠结谁第一，该按价格与流程顺手度选。** 第二条是**真实的成本账**，可直接拿去报价：720p 模型收费 1.5–1.6 元/秒，生成一分钟 90 元；同一镜头抽卡三遍，每分钟算力成本近 300 元；AI 影视制片人小七说，精品短片改几十次，一分钟成本可能上千块。价格水位也在往下：Gemini Omni 1.2 Flash 720p 降到 0.07 美元/秒（约 0.47 元），比上一代低 30%，约为 Seedance 2.5 同档的三分之一；Vidu Q4 Preview 首发优惠 0.09 元/秒。第三，**这门生意还没有人算平**：OpenAI 今年 3 月关停 Sora，停前每天亏约 100 万美元；可灵预计到 2028 年第四季度才能单季盈亏平衡；字节 Seedance 2.0 被曝单月营收超 10 亿元（火山引擎总裁回应称外界数据“普遍偏高”）。第四，**短剧是最大的买家**：国内 Token 消耗中 AI 短剧与视频生成占 55%，Seedance 在短剧行业渗透率约 95%；而 AI 短剧项目里**投流通常占流水 70%**——制作省下来的钱，大头又交回了投流。文末那句判断值得记住：**“如果模型能力继续趋同，单纯卖模型的一方，最后很可能沦为流量平台的供应商。”**",
