    "summary": "浙江一位爸爸把 3 个月大的宝宝举起来拍视频，孩子身体绷直、平行地面像小超人，评论区吵成两派——有人提醒警惕肌张力高，有人说这很正常；爸爸回应说已经在给孩子按摩。",
    "takeaway": "这条的母题是新的，我们之前没采过：**“晒娃”变成了“被远程诊断”**。爸爸的本意只是记录或者炫耀，评论区却开始给他的孩子下诊断书——可爱和不安在同一个画面里。**画面本身就是钩子**：一个男人把三个月的婴儿举过头顶，孩子身体笔直像超人，这个动作有多逗，后面就有多凉。冲突结构也很干净：两派网友各执一词，家长夹在中间，**“要不要现在就去医院”是一个不能立刻回答、又必须回答的问题**。台词可以只有一句：**“别靠一条视频猜我孩子的肌张力。”** 结尾不需要答案，停在父亲深夜给孩子按摩的那双手上就够。**医学红线必须标死**：这是短视频新闻，没有任何诊断结论，片子里不能给出任何判断，也不能暗示“网友说对了”或“网友在瞎猜”——只要呈现那种被围观、被越界的不适就够了，否则会变成传播医疗建议。",
