    "source": "新黄河 2026-11-19 18:34（搜狐号转载），记者任晓斐；受访者为《持械入宋》总策划张汉生、总编李朝华、总导演何秀山",
    "url": "https://news.sohu.com/a/1103761456_121347613",
    "heat": "只有讨论度，无数字（搜狐页面不显示阅读与评论数）。背景可核：《持械入宋》已是红果 AI 短剧热播榜头部作品、连更 11 季，该数据见第 128 期",
    "summary": "《持械入宋》主创首次系统讲方法：30 多人、核心 6 人全线上协作，按“有效成片时长”分成、废片不计入；多人风格靠“人设和场景资产库”统一。",
    "takeaway": "**最值钱的一条是他们的“废卡”标准**——何秀山原话：**“有的镜头一次过，有的抽几十次。即便是没有穿帮、演绎正常的镜头，如果它只有 60 分，很平，我们也认为是废卡。”** 抽卡多不是因为镜头不好，是因为没达到自定标准。**第二条解决了多人分工的老问题**：不同创作者“提示词的风格会有差异，但最终统一在人设和场景的资产库里”，而真正的一致靠的是“对剧本的高度统一理解”——人物走向、故事走向、人物性格，每个人都要吃透。**第三，结算方式本身在管质量**：按“审核通过的有效成片时长”分成、废片不计入，人不在一起却不用催进度，因为“做得越多赚得越多”。团队 30 多人、核心 6 人，全程线上（微信、飞书、网盘、腾讯会议），甚至有一条“不开会原则”。**第四，草根经历就是素材**：那集“小兵第一人称视角爬城墙”的设计者，是团队里一位做过送货员的成员，因为“他想让战场更真实”。技术侧一句：从 2.0 转战 2.5，对群像剧和大场面帮助很大。**最后是一盆冷水**：张汉生说今年下半年全国很多 AI 短剧公司陷入经营困境，**“AI 技术已经不是问题了，最重要的是内容和创作思路。AI 本身没有感情，家国情怀、情绪，都是人赋予给它的。”** 何秀山更直白：最怕新闻被误读成“所有人都能靠 AI 短剧获得巨大收获”。",
