    "summary": "AI 短剧已成短剧主流，但爆款在榜天数从中位 6 天缩到 4 天、断层爆款消失；同时赵丽颖起诉红果 AI 换脸引出版权红线，行业下一步靠长线 IP 而不是产量。",
    "takeaway": "**最重要的一条不是效率数据，是红线**：红果短剧 11 月 17 日就“肖像侵权”发专项治理公告，从平台自审、制作预检、侵权投诉三个环节收紧——导火索是不经授权抓取赵丽颖面部特征合成进短剧角色和封面，明星方起诉，话题阅读近 5 亿。对我们意味着：**用真人明星脸、网红脸做 AI 角色或封面，已经从“可能被诉”变成“平台会主动查”**，比任何出片效率都该先确认。数据层面三件事值得记：①**爆款保质期在缩短**——6 月有 280 部 AI 剧进过红果 TOP100，7 月增至 339 部，单部在榜天数中位数从 6 天降到 4 天，热度差距变小、断层爆款缺失；②**赢面比体感小得多**——上半年抖音端上新 22.19 万部、破亿 1055 部、破亿率约 0.48%（此数与第 122 期重复，不重复计入）；③**下半场拼 IP 长线**——《持械入宋》连更 11 季、上千集，靠新一季热度反哺第一季；《万妖图录传》第 14 季已上、第 15 季站内预约 343 万，《云州异客》预约 433 万；11 部热门剧中过半有明确长线计划。还有一条反面教材：AI 角色“方桃子”运营方因虚假美瞳广告被罚 6.8 万余元——**AI 人物商业化同样受广告法约束**。另：超 75% 的热门 AI 短剧改编自网文，母题已被市场反复验证，同质化也因此极重。",
