    "heat": "只有讨论度，无数字（网易号页面 0 条跟贴）；文中细节可核：四川家长投诉一年级视频打卡任务、“去年底一个家长参与护学岗值班，猝然倒地身亡”",
    "summary": "一篇批评家长负担的评论：双减后纸笔作业少了，视频打卡、拍照上传、批改核对却从校园转到千家万户，“学生减负、教师减负，落地就成了家长负担的增长”。",
    "takeaway": "把三件事讲透了，其中**两条可用于片子的硬信息**：一是“学校里的自愿常是伪命题”——护学岗、班级值日、主题实践打卡在很多地方已经形成排班表、按学号轮到每个家庭，没有强硬命令，多由家委会转达、群里倡议，家长怕影响孩子只能就范；二是**去年底有家长参与护学岗值班时猝然倒地身亡**，这一条把“权责边界模糊”从抽象变成了具体的风险。几句可直接当台词或字幕的判断：**“协同育人不等于联合卷人”**、**“家委会是沟通桥梁，不是学校的执行分支机构，无权代学校执行任务”**，以及结尾那句反问——**“在打卡、值班和批改作业间疲于奔命的父母，能培养出从容成长的孩子吗？”** 还有一层常被忽略的连带伤害：对教师而言看似分担了工作量，却稀释了专业性，“家长都在做了，还要老师干什么”。提醒：**这是自媒体评论，核心事实（护学岗猝死）需另找原始报道核实**；且主题与第 31、41、103、109 期同源，**别当新事件立项**，可作那几期的“后果补充”——它是唯一提到人命代价的一条。",
