    "url": "https://w.geekpark.net/news/374133",
    "heat": "数据可核：Phai-M1 生成一段 15 秒 720P 视频约需 3 分钟；Phai-A1 同单卡 RTX 3090、相同代码智能体任务下响应速度较 Qwen 27B 提升约 8—10 倍；两款模型均完成华为昇腾平台全流程后训练优化，并计划开源权重",
    "summary": "范式发布 Phai 系列两款自研模型：语言模型 Phai-A1 与视频生成模型 Phai-M1，其中 M1 以真人影视场景为训练重心，支持音画同步，15 秒 720P 约 3 分钟出片。",
    "takeaway": "这条跟我们关系最直接的是 **Phai-M1 的定位——“面向真人影视场景”**，优化的是人物表情、肢体动作与画面细节，针对的正是 AI 视频最常见的失真；而且它**支持音画同步生成**，同一流程里出画面和音频。效率数字也实在：**15 秒 720P 约 3 分钟**。对比第 118 期那组实测（Seedance 2.5 出 10 秒要 10 分钟、Kling 4.0 最快 2 分钟），这个速度属于第一梯队。另外两点值得记：一是**计划开源模型权重**，如果真开源，本地部署和成本控制的空间会大很多；二是**全流程在华为昇腾平台完成训练优化**，是国产算力的一个信号，对企业自主可控有意义。还有一个参照物：Phai-A1 在同单卡 RTX 3090 上响应速度比 Qwen 27B 快约 8—10 倍，且能本地部署、原生百万级上下文。提醒：目前是发布通稿口径，没有第三方实测；“计划开源”也还只是计划，别当已可用写进方案。",
