    "title": "17 岁女孩确诊高危白血病，父母用三个“善意的谎”托住她",
    "source": "新快报 2026-11-19 08:16（网易号转载）“温暖 1817 号”，记者潘芝珍、李斯璐，通讯员何家祁；患儿 17 岁，就读公办高中，在中山大学肿瘤防治中心治疗",
    "url": "https://www.163.com/dy/article/LC36UI0S0534AAOK.html",
    "heat": "数据可核：女孩 17 岁、今年春节期间发现颈部肿块、确诊高危急性 T 淋巴细胞白血病（癌细胞侵入骨髓 80% 以上）、自费部分已超 20 万元、临床治愈率逾 50%、治疗周期超两年",
    "summary": "广东湛江籍务工家庭的 17 岁女孩小曼确诊高危白血病，父母对她撒了三个善意的谎：瞒着 81 岁奶奶说只是淋巴瘤、在女儿面前绝口不提借钱的窘迫、对来看望的同学也委婉拿捏探望分寸。",
    "takeaway": "这篇的价值是**把“善意的谎”拆成了层次分明的三个**，这在同类题材里少见：**第一层对老人**——只说“普通淋巴瘤，很快就好”，为了维系这个谎，夫妻俩不敢让女儿和奶奶视频，女儿还要强打精神在电话里说“奶奶，你别太累，我们很快就能回去”；**第二层对病人**——借钱、筹钱、打听救助全部避开女儿做，从不在她面前提开销数字，还告诉她“医疗技术越来越发达，这种病一定可以百分百治好”，刻意隐去“高危”“复发风险大”这些词。父亲的解释很准：**17 岁的孩子已经足够懂事，知道代价，愧疚感会压垮她的求生意志**；**第三层对外人**——同学跨城来探望，他开心也害怕，于是在分寸间平衡说辞，“有时提醒大部队拆小分队，有时委婉拖延探望时间”，不直说怕细菌怕吵闹。这一层最微妙，也最适合做戏。可拍的实物：脖子两侧的硬块被她放下长发遮住、鹌鹑蛋大小的肿块、“不痛不痒，但越长越大”。提醒：**这条与第 73 期、第 99 期同为白血病题材，已经是第三次**，我照实报备；要用建议单独立项，别和那两期挨着排。另外涉及真实患儿与募捐（文末附恤孤助学促进会账户），改编须授权，且不要写成求助广告。",
