    "source": "OFweek 维科号 2026-11-19 09:11，作者“数智奔流”，署名熵野、沈校；综合商汤官宣、观察者网、36 氪等多家采访",
    "url": "https://iot.ofweek.com/2026-11/ART-132200-12003-30712408.html",
    "heat": "数据密集且可核：商汤 11 月 10 日前后官宣该剧“登榜首”、随后推文被设为仅自己可见；主创 6 人（非传言的 30 人）；红果 7 月末 DAU 1.68 亿（+107%）；2026 年一季度 AI 微短剧占比超 95%；上半年抖音 AI 剧 22.19 万部、播放破亿不到 0.5%",
    "summary": "一篇调查式行业分析：商汤发文宣称《持械入宋》是 Seko 生态爆款，但主创团队在多轮采访里提到的工具是 Seedance 2.0／2.5 和豆包，唯独没有商汤；商汤随后把该推文设为仅自己可见。",
    "takeaway": "这是目前读到最有信息密度的一篇 AI 短剧行业稿，**核心是一次“功劳归属”的核对**：商汤官宣称“10 人核心团队分 5 组并行、基于 Seko Agent 体系化能力，一周一季、一季 100 集”；而主创在观察者网、36 氪的采访里说的是**核心 6 人**、分散在河北吉林湖北线上协作、11 月 5 日三人才在火车站第一次见面，工具是“抽卡主要用 Seedance 2.5，第一季开头用 2.0”，剧本“我用豆包”。两边唯一的交点是雪宝工作室——老十一剧场创始人张汉生是雪宝 2025 年培训课第 11 号学员，但两者没有工商隶属关系。**这条线索对我们判断“谁在真做内容、谁在做生态叙事”特别有用。** 另外几个硬事实值得记：Seko 自研清单里，**真正被外部验证的是推理框架 LightX2V**（被 ComfyUI 官方集成、GitHub 约 3000 星，第三方测试显示四步 LoRA 让 Wan2.2 生成 5 秒视频时间缩短 85%，代价是运动幅度下降）；而本该对标的视频模型 Seko 1.5 **公开资料最少，找不到模型卡、技术报告或盲测成绩**。两位负责人的话很关键：“**模型能力不是价值的最终交付**”“**一个模型的生命周期大概半年**”——这解释了商汤为什么把筹码押在生态和产线而不是画质。提醒：本文为维科号作者观点，涉及具体归属争议建议以商汤官宣原文与主创采访为准。",
    "status": "备选",
    "tags": [
      "持械入宋",
      "商汤Seko",
      "功劳归属",
      "行业调查"
    ],
