    "summary": "重庆一所学校办 10 公里亲子跑，家长张雪陪女儿跑完全程，怕她跑不动直接把女儿背起来跑，还把女儿和同学一手一个抡起来转圈；受访时他说怕自己跑不赢女儿，也希望所有小朋友“跑快一些，超过你爸妈”。",
    "takeaway": "这是难得的一条**清爽型**素材，没有冲突、没有说教，全靠两个动作支撑：**背起来跑**，和**一手一个抡起来转圈**——第二个动作尤其好用，它不解释父爱，直接让人看见。全片最好的一句台词是他那句自嘲：**“怕我跑不赢她”**；更值得当片尾的是对着一群孩子说的那句——**“希望所有的小朋友跑快一些，超过你爸妈”**。这句把“父母希望孩子超过自己”讲得又轻又准，比任何励志台词都有力。形式上建议就用一场比赛的时间线，10 公里、配速、补给点、最后冲刺，中间只插这一个背起她的动作，不要加旁白。提醒：张雪是公开报道中的家长，但报道未交代其身份，引用时别自行加头衔；涉及未成年人，画面须取得家长与学校授权。",
