    "url": "https://cloud.tencent.com.cn/developer/article/2788366",
    "heat": "只有讨论度，无数字（社区文章，未见阅读/点赞计数）；文中称 11 月 19 日“AI版武大郎潘金莲太真实”冲上微博热搜",
    "summary": "11 月 19 日“AI 版武大郎潘金莲太真实”冲上微博热搜：做旧画面、颗粒感、刻意压低的清晰度，加上端药时抬眼看人的微表情，评论区一片“像拍的剧”“监控流出”，却少见创作者主动标明 AI 生成。",
    "takeaway": "这条接在第 108 期（“古早监控”的走红与红线）后面，正好构成一组对照：**上一轮是靠“古早监控”的形式新鲜，这一轮是靠“像真的”本身。** 值得记的是它点出的手法清单——**做旧的画面、颗粒感、刻意压低的清晰度**，加一个**微表情**（端药时抬眼看人），四样东西就足以让观众喊出“像拍的剧”。这几乎是一份“如何让 AI 看起来像实拍”的说明书，对我们的**伪纪录风格**项目可以直接用。但文章真正想说的是另一件事，也是它标题的意思：**到现在没有创作者公布用了哪套工具，也很少有人主动标一句“AI生成”——标注成了最后一道防线**。这跟我们第 87 期采到的合规要求是一条线（9 月 1 日起 AI 微短剧须在每集明显位置加提示标识）。判断很清楚：**越像真的，越该标明是假的**，否则观众没法分辨，创作者也没法自保。提醒：本文正文只取到概述，未展开具体案例与判罚，引用时以标题与概述为准。",
    "status": "备选",
