    "title": "作业之外……：八岁女儿写到十点半，电话手表响了却只能说“我在写作业呢”",
    "source": "《黔南日报》2026-11-19 第 06 版副刊，作者王綮（家长本人投稿散文）",
    "url": "http://paper.qntv.net/html/2026-11/19/content_52012_20036945.htm",
    "heat": "只有讨论度，无数字（报纸副刊，无阅读/评论计数）；文中细节可核：孩子 8 岁、读三年级、写到十点半仍未完",
    "summary": "一位妈妈写女儿写作业写到十点半：八岁三年级，作业有语数英科加葫芦丝、练习册、抄写、背诵、打卡，楼下孩子都睡了，她还趴在台灯下写。",
    "takeaway": "这是本期最好的一条，而且是**家长本人写的一手散文**，细节密度高到可以直接当分镜脚本。全篇的“戏眼”是那通电话手表：楼下小朋友奶声奶气地喊她下去玩，**她低头看了一眼摊开的作业本，抿了抿嘴，小声说“我在写作业呢，去不了”**；电话那头沉默两秒，说了句“好吧”就挂了；她放下手表没说话，又拿起笔——**可眼圈又红了**。这一分钟足以撑起整条短片。其他可用的实物：只开一盏台灯的客厅、**握笔的手指关节泛白**、打哈欠涌出眼泪用手背胡乱一抹、**“妈妈别催，还有两页”**、红着眼眶说“不行，老师会批评的”、写着写着眼泪啪嗒啪嗒掉在本子上说“**妈妈，我想转学，我不想上学了**”。还有一个残酷的对照：妈妈回忆自己小时候放学像小鸟飞出教室、跳皮筋到妈妈喊吃饭，而女儿的**画笔落了灰、舞鞋塞进柜子最深处、课外书一本没翻开**。结尾那句分寸感极好，别改：**“我不知道以后会怎样，也不知道这样做对不对。我只知道，今晚我想让她早点睡。”** 以及最后一句——“那就先睡吧，明天再说！”提醒：副刊散文属文学作品，改编需联系作者或报社授权；另外它和“双减”“作业量”话题相邻，但别把片子做成政策控诉，它写的是一个妈妈的心疼。",
    "status": "备选",
