    "title": "“后知后觉，十几年前那个和我聊天的网友，应该是我妈妈……”",
    "source": "新浪财经 2026-11-14 原帖转载，中华网 2026-11-18 10:22 转发；光明网、澎湃新闻、北京时间均有报道",
    "url": "https://news.china.com/socialgd/10000169/20261118/49883217.html",
