    "summary": "一位博主回忆：十几年前她刚有 QQ 号，每天守在电脑前没人聊天，妈妈偷偷注册了一个叫“心语心愿”的账号，假扮 12 岁小姑娘陪她说话；多年后她问起，妈妈坦然承认“是我呀”。",
