    "title": "实拍×AI 混剪不穿帮的关键只有一个：参考图必须用实拍画面去喂",
    "source": "川观新闻「AI工坊笔记⑤」2026-11-19 10:40，记者高永虹、葛仙雅；课程为超级创作者 @Mr.多多 的《可灵AI商业实战从基础到进阶》第 1 讲",
    "url": "https://cbgc.scol.com.cn/news/8151272",
    "heat": "只有讨论度，无数字（川观新闻页面显示 0 条评论、13 次点赞）；文中给出可核实操比例：一条十几分钟的片子里约 40% 分镜用 AI 生成",
    "summary": "AI 工坊笔记第五期讲实拍与 AI 混剪：一条十几分钟的片子里约 40% 的分镜用 AI 生成，插进实拍素材直接混剪，不穿帮的关键是参考图必须用实拍画面去喂。",
    "takeaway": "这条可以直接写进我们的作业规范，因为**它把“AI 素材怎么用”这件事讲反了直觉**：多数人以为 AI 素材是“另外做一批”，讲师说不是——**“AI素材不是‘另外做一批’，是‘接着实拍那批往下做’”**。关键动作只有一个：**参考图必须用实拍画面去喂**。他的原话是“我的参考图是用实拍的一些画面去参考的，所以它生成出来的东西跟当时的影调质感是一致的”；反面例子是用网图或纯文字生成做参考，**影调、色温、颗粒全对不上，插进去就违和**。还有一个可用的比例：**一条十几分钟的片子里，大约 40% 的分镜用 AI 生成**，观众很难看出区别。最适合用的场景也很实际：拍摄周期被压缩、大量场景没拍到、回去重拍成本无法覆盖。开场那句比喻可以留作组里的共识：“AI 像神笔马良，但它不替你决定画什么”；以及那句提醒——**“人数可以节省，思维和判断节省不了”“工具把‘手’的成本压到接近于零，‘眼’的高低就成了唯一的差距”**。下集预告里有个信息先记着：第 2 讲会讲**提示词的七段结构**，以及 JSON 提示词什么时候值得用。提醒：这是课程笔记转述，非实测数据，40% 是经验值不是标准。",
