    "title": "14 岁初中生发帖被起诉，账号登记人是爸爸和爷爷：未成年人上网，责任落在谁头上",
    "source": "腾讯新闻 2026-11-17；受访律师为浙江京衡（上海）律师事务所朱旻，其解读见报道全文",
    "url": "https://news.qq.com/rain/a/20261117V0AJCI00",
    "heat": "只有讨论度，无数字（腾讯新闻聚合页未给阅读/转发计数）；案件细节可核：发帖人自述为 14 岁在读初中生、2025 年初转载涉争议内容、评论数 24 条、涉案账号登记主体为其家属",
    "summary": "一起名誉侵权纠纷里，发帖人疑似 14 岁初中生，涉事账号登记的却是她父亲和爷爷；律师解读：民事侵权没有年龄免责，8—16 岁限制民事行为能力人造成损害由监护人承担替代责任。",
    "takeaway": "这条的普法点非常清楚，而且是很多家长真不知道的：**民事侵权不像刑事，年龄上没有免责一说**——不满 8 周岁的无民事行为能力人、8—16 周岁的限制民事行为能力人造成他人损害，**由监护人承担替代责任**；而未成年人只在其能力范围内担责，比如名誉侵权案里**赔礼道歉属于她能承担的责任，涉及金钱赔偿则一般由监护人兜底**。更值得做片子的是那个细节：**账号登记在父亲和爷爷名下**——这几乎是所有家庭的默认操作，用大人身份证给孩子注册，平时图省事，出事时才发现责任的落点完全不一样。这一层可以直接做成短片的核心冲突：孩子以为自己在网上说话，家长以为账号是自己的“授权”，真出事时法律看的是登记人。提醒：涉真实未成年人、且是娱乐纠纷，改编务必匿名并避开案件细节；与第 101 期（游戏账号注销）、第 12 期（防沉迷）同属“数字时代育儿”，但那条讲的是管理方式，这条讲的是**法律后果**，可作为对照。",
