    "title": "每周半天校外实践课要全国推行：深圳做了两年，呼和浩特做了一年",
    "source": "舜网·理响泉城时评 2026-11-19 07:27，作者焦小超；政策信息源自 11 月 18 日新华社报道教育部基础教育司司长田祖荫在新闻发布会的表态",
    "url": "http://opinion.e23.cn/a/2026-11-19/225420",
