    "title": "两个人 30 天做出 21 分钟 AI 剧集《原基》，拿下全球 AI 影视大赛冠军",
    "source": "2026-11-18 10:41 转载稿（本页为爱星座网转载，原始信息源为上海市徐汇区政府官网 11 月 13 日发布的创作者故事）；创作者为 TAPNOW 签约工作室“绝对黑场”的刘浩男、乔宇航",
    "url": "https://www.a-xingzuo.com/2026/1118/63222.shtml",
    "heat": "数据可核：片长 21 分钟、2 人、30 天做出第一集（平均每天约 42 秒成片）；获“一万个平行宇宙”全球 AI 影视创作大赛冠军；今年 9 月初在第 83 届威尼斯电影节“制作桥”单元展映，《VARIETY 综艺》专题报道",
    "summary": "两个有传统影视经验的创作者用 30 天从零做出 21 分钟科幻 AI 剧集《Primordia 原基》，先拿下全球 AI 影视大赛冠军、进了威尼斯电影节产业单元，再回国把工作室落在上海的可灵创作者社区。",
    "takeaway": "这是继第 100 期《狂潮》之后又一个硬案例，但**它的价值在于把“素人逆袭”的神话戳破了**：两位创作者是高中同学，都热爱科幻电影，都有数年传统影视行业经验——**他们带来的恰恰是 AI 最缺的东西：镜头语言的经验、叙事节奏的判断，以及知道一个科幻世界需要多少细节才立得住**。文中那句比喻值得抄进组里：**“模型可以生成星舰，但不知道星舰该从哪个角度入画才有压迫感。”** 分工也清楚：刘浩男是视听导演兼视觉总控，管影像调性、镜头调度、星际战舰与外星地貌；乔宇航是故事导演兼编剧，搭宇宙设定与人物主线。更难得的是这篇文章自己划了三条边界，比吹捧有用得多：①**单部获奖不等于可复制产能**——影展评的是完成度与创意，不是排播稳定性；②**科幻是 AI 最友好的题材**，没有真人微表情难题、场景几乎全能生成，而都市情感、家庭伦理、喜剧这些依赖表演与生活质感的品类，AI 完成度还差得远；③商业模型未披露，奖项给的是信用背书不是现金流。收尾那句可以直接当工作室的判断句：**“2026 年的 AI 影视已经过了‘能不能做出来’的阶段，进入‘能不能持续做、能不能卖出去’的阶段。前者靠模型，后者靠工业。”** 提醒：本页是星座站转载，引用请回到徐汇区政府官网原文或《VARIETY》报道核实。",
