    "title": "秋假托管“一个人的教室”：全校只来了一个学生，方案照样执行到最后一分钟",
    "source": "扬州日报·扬州网 2026-11-19 07:57，记者刘冠霖；事发扬州文津中学，11 月 16 日为扬州义务教育阶段首个秋假首日",
    "url": "http://news.yznews.com.cn/2026-11/19/content_7856608.htm",
    "heat": "数据可核：扬州义务教育阶段首个秋假，全市近 34 万中小学生放假；文津中学托管报名截止时只有 1 名学生（初一 12 班杜秋怡）；当天 8:20 入校、17:00 交接离校",
    "summary": "扬州首个秋假，文津中学的托管班只报上一名初一女生，学校仍然按“一校一案”把一天排满：早锻炼打羽毛球、图书馆阅读、整理借阅亭、操场跑步，教师掐表陪跑、副校长在终点线等她。",
    "takeaway": "这是近期最干净的一条正面素材，**不苦情、不说教，全靠流程本身打动人**，而且画面是现成的：一个人的教室、一个人的体育馆、一个人的跑道。最好的一句台词是学校书记的原话——**“托管是刚性承诺，不是规模生意。报一个，我们就按方案托管一个。”** 另一句是体育老师李海兵的：**“秋假不授课，但孩子的身体不能放假。”** 结构直接照着那天的时刻表走就行：8:20 校门口等 → 热身 → 打羽毛球“一拍一拍喂过去” → 图书馆（副校长陪着，不会的题问她）→ 下午整理四座借阅亭（写进方案的“小活儿”，一个多小时整理整齐）→ 16 点跑道，老师掐表陪跑、副校长在终点线等 → 跑完师生三人坐在台阶上 → 17 点家长来接，签到表落下交接时间和双方签名。最后那句报道原文可以直接当片尾：**“看护名单上只有一个学生名字，但托管方案被完整、规范、不打折扣地执行到了最后一分钟。”** 提醒：与秋假系列（第 15、33、56 期）同属一个政策背景，但角度完全不同——那几期讲争议和制度，这期讲执行，可当“秋假”议题的收尾片。",
