    "title": "AI 短视频“古早监控”走红：用第三视角监控拍武松打虎、司马光砸缸",
    "source": "辽宁日报 2026-11-19，作者朱忠鹤",
    "url": "http://epaper.lnd.com.cn/lnrbepaper/pc/con/202611/19/content_344873.html",
    "heat": "只有讨论度，无数字（报纸评论，未给播放量/点赞数）；文中称此类视频“这几天又在网上火了”，与 AI 说唱《过来人》同属近期爆款",
    "summary": "一类叫“古早监控”的 AI 短视频走红：创作者用 AI 生成第三视角监控画面，带雪花噪点、时间戳等监控标记，重现武松打虎、司马光砸缸等经典故事，像“在古代保安室看监控”。",
    "takeaway": "这条不是工具，是**一个可以直接抄的内容形态**，而且它把“为什么火”拆得很清楚，三件事：①**第三视角制造“古早现场”感**——符合人的探秘心理，既刺激又有悬念；②**把静态转成动态情节化**——石头怎么砸、老虎怎么扑、水怎么流出来，全变成具象画面；③**加幽默感和人情味**——让古人不再是被供起来的固有印象，而像身边有脾气、有性格的现代人。这篇最大的价值是一句判断：**“好的内容并不等于好的传播”**——故事再经典，讲得硬邦邦、离普通人太远，也很难传播；“原本应该被更多人看见的文化资源，就因为‘板着脸’传播，把很多人挡在了门槛之外”。同一个逻辑它举了 AI 说唱《过来人》——让李白、杜甫、苏轼现身说法，不堆大道理、不站道德高地。**红线也划得明确**：不能移花接木、误导公众、扰乱舆论；历史可以幽默，但不能把二创低俗化的做法直接用在野史里。对我们做文化类短片，这条既是形态灵感也是合规提醒。",
    "status": "备选",
