    "title": "家校共育边界在哪？矛盾如何化解？——杭州“督学之家”与济南“小小调解员”",
    "source": "《科教新报》2026-11-18 第 16 版“深读”，转自新闻联播微信公众号，来源为湖南日报报业集团",
    "url": "https://epaper.voc.com.cn/kjxb/html/2026-11/18/content_1808172.htm",
    "heat": "只有讨论度，无数字（报纸版面，无阅读/评论计数）；文中引用案例与数据可核：四川多地教育部门介入督促整改、首都师范大学问卷调查、广西河池/浙江诸暨/广东韶关叫停强制护学岗、杭州拱墅区划分 11 个片区每片区 5—7 名督学",
    "summary": "一篇家校共育的深读综述，前半段盘点家长负担与非理性投诉，后半段给出真正的解法：杭州“督学之家”把督学、家长、社区、法治副校长请到一张圆桌，济南学校在班里培养小小“调解员”来前置化解矛盾。",
    "takeaway": "这篇前三段（三类责任转嫁、护学岗叫停、非理性举报）和第 31、41 期重合，**真正新的是后半段那两个机制案例，也是唯一值得拍的部分**：一是杭州文晖实验小学的“督学之家”——督学、家长代表、社区工作人员、法治副校长坐一张圆桌细化接送方案，之前校门口人车混杂，多方商议出连通社会停车场、人车分流的办法；拱墅区把全区划成 11 个片区，每片区 5—7 名督学，还组了“公众督导团”，这不只是议事平台，还承担矛盾前置调解。二是济南高新区科创路学校的“玉帛润心”——联合社区和仲裁委在校园里设调解室，**每个班培养一批小小“调解员”当“润心使者”**，化解学生之间、师生之间、家校之间的矛盾。后者尤其适合做片子：让小学生去做大人的调解员，天然有戏。另外两条硬信息值得记：首都师范大学问卷调查显示教师与家长在协同育人上“立场、关注点存在差异”；教育部教师工作司已明确提出将规范涉师争议投诉处理程序、对不实举报及时澄清正名。提醒：与第 31、41 期同源，**别当新事件立项**，可作那两期的“解法补充”。",
    "status": "备选",
