    "summary": "人民锐评点名短视频平台上的家庭教育乱象：主播打着“高级家庭教育指导师”“高级心理咨询师”旗号，拿“原生家庭”说事，把孩子的问题归咎“父母失职”，顺势兜售高价课程与训练营。",
    "takeaway": "这是官方定调，价值不在信息量而在“可以直接引用的判断”。最锋利的一句是套路总结：**“先制造焦虑，再兜售方案”**，配套的话术样本也该记下来——“几天改变孩子、几节课修复关系、一套方法解决厌学叛逆”，评论说这是“把成长难题包装成明码标价的商品”。定调句可直接当片尾：**“家庭教育不能靠‘速成班’，也没有所谓的‘特效药’”**；以及对专业的定义——“真正专业的指导，应基于科学评估和长期陪伴，而不是用愧疚感诱导家长付费”。它还给了一个很少被说的反面视角：伪专业能占市场，是因为**正规服务供给不足**——身边资源要么稀缺、要么昂贵、要么不知道该信谁，学校指导也常停留在办讲座、发材料。这比单纯骂骗子更有戏。提醒：与第 67 期（封面新闻暗访“杀猪盘”）是同一现象的不同文体，67 期是暗访细节、这期是官方表态，建议配合使用、别当两条独立选题。",
