    "title": "“您可以回去了”：云南一所小学立提示牌，劝家长别再送忘带的东西",
    "source": "新华网云南频道 2026-11-18 16:30，新华网原创新闻，作者范芳钰、刘起、汪凌杉；资料来源文山市融媒体中心，事发云南省文山市第十二小学",
    "url": "http://yn.xinhuanet.com/20261118/bf9001b80b674d6084b4bcdc3073b7f6/c.html",
    "heat": "只有讨论度，无数字（新华网原创报道，未给阅读/转发计数）；文中称该提示牌“在社交平台引发热议”，配图为 11 月 12 日摄",
    "summary": "文山市第十二小学校门口立了一块提示牌，劝来送“作业、书本、学具、鞋子、水壶”的家长回去，理由是家长及时兜底会让孩子缺少自我检查、自我负责的意识。",
    "takeaway": "这是近期最“能拍”的一条，因为全片只需要一个道具——一块牌子。原话就是最好的台词，一个字都不用改：**“亲爱的家长朋友：如果您是来给孩子送他忘在家的作业、书本、学具、鞋子、水壶等物品的，您可以回去了……”** 更妙的是清单本身，“鞋子”两个字一出来，荒诞感和真实感同时到位。校长的解释是完整的因果链：家长及时兜底看似解决眼前麻烦，久而久之孩子形成依赖、缺少自我检查和自我负责的意识，遇到问题习惯等家长帮忙。最好的一段是学生反馈——**有了这块牌子，家人没有再送过东西，自己慢慢学会收拾，也没再忘带过课本**，这是全片唯一需要的“结果”。也要拍进去反面：有家长认为低年级孩子还是需要适应过程，别做成一边倒的说教。片尾可用报道那句“一块提示牌，让大家看见家校共育里动人的分寸感”。提醒：新华网原创，引用需署名，拍摄校门口需学校授权、避开学生正脸。",
