    "title": "儿子被3家医院确诊谱系，两年后邹小兵评价“程度很轻”：这位211硕士爸爸做对了什么",
    "source": "大米和小米 2026-11-15 18:14（网易号），内容据小七爸爸在大米和小米的直播整理，整理者卡恩；受访者为 211 硕士、原世界 500 强高级产品经理",
    "url": "https://www.163.com/dy/article/LBPVJIT7052682N1.html",
    "heat": "只有讨论度，无数字（网易号页面 0 条跟贴；未标注观看量）；关键节点可核：2019 年底 5 岁确诊、2021 年 5 月邹小兵复诊评价“程度很轻”、现 10 岁读普校四年级",
    "summary": "一位 211 硕士爸爸在儿子 5 岁被三家医院确诊谱系后辞职回家做家庭干预，两年后复诊被告知“程度已经很轻”，如今孩子 10 岁在普校读四年级、有了自己的朋友圈，他复盘的核心是“社交帮扶三步走”。",
    "takeaway": "这是本期最好的一条，而且是一手直播整理，不是二手转述。最值钱的是他把“不社交”拆成了可判断的类型：一类是**没有意愿**（逃避型——宁肯等所有人都走了再一个人玩；忽略型——人都在但像罩了金钟罩），另一类是**有意愿但做不到**（被动观察型——一直在评估“我能不能做到”，还没评估完别人已换了花样；主动但乱来——上来就抢，不是坏，是不知道怎么表达“我想一起玩”）。这个分类本身就是剧本的人物设定表。方法也极具体：先在家打两样基础——**游戏力**和**依恋关系**，再往外走三步——**适应氛围（带着他喜欢的恐龙玩具去草地，这一步没有任何社交要求）→ 轻量级介入（带一个能吸引人的玩具，家长先代孩子去跟小朋友搭话、给两个孩子各派一个任务）→ 培养固定玩伴（就近下手、加微信、约下次）**。两句可直接当台词的：孩子像“一只孤零零的鸟，看着别的鸟成群结队地飞”；以及结尾——**当孩子和小伙伴关起门玩，对你说“大人别进来”，你就知道他真的融进去了**。立意落在他那句“与其说是在干预孩子，不如说是在改变自己。我变了，孩子才跟着变”。注意：涉及真实患儿与家庭，改编须授权，且不要把干预方法写成疗效承诺。",
