    "summary": "火山引擎官方 Seedance 提示词规范的完整中文版，含基础/进阶公式、分镜时序的正确写法、音效台词字幕的符号约定，以及人物漂移、双胞胎、多余字幕等官方实测避坑清单。",
    "takeaway": "这正是我上次说抓不到正文的那份官方文档——官方页是 JS 渲染读不出来，这次在 GitHub 上找到了同步镜像，我核对过内容与官方口径一致。四条最该立刻改的：①**分镜时序别再写“0-3秒”**——官方明确说模型对精确时间支持不稳定，强行限制时长可能导致生成异常，正确写法是按“镜头1／镜头2／镜头3”组织，快慢用“快速／缓慢／随即／片刻后”这类相对词代替秒数；总时长写进约束并在面板选长度，精确卡点绑 @音频。②**符号约定**：音乐用（）、音效用 <>、台词用 {}、字幕用【】，台词语言要统一，别中英混用。③**一个镜头只指定一种运镜**，同时推拉摇移会增加不稳定性。④**人物一致性别用三视图**——官方说三视图容易被模型当成多个主体、反而加剧漂移，正确做法是一张只含头部的大头照（无表情最佳）+ 一张全身照，且越要精准参考的素材放越靠前；同一画面禁止出现外形着装完全一致的人物，要加全局约束。另外两条硬限制要记：参考视频最多 3 段、总时长 ≤15 秒；延长拼接处跳变的解法是“前一段末尾删 6 帧、后一段开头删 1 帧”。还有一条反直觉的：**优先横屏生成**，横屏出多余字幕的概率明显低于竖屏，后期再裁竖屏。",
