    "title": "如何驯服 AI 做出你想要的视频：C.R.E.A.T.E 公式与长镜头“化整为零”",
    "source": "新京报 2026-11-02，网易号转载；主讲人为新京报社动新闻高级编导王瑾，讲座在北京信息科技大学举行",
    "url": "https://www.163.com/dy/article/LANM21230512D3VJ.html",
    "heat": "只有讨论度，无数字（网易号转载页 0 条跟贴；无阅读计数）",
    "summary": "一位从业十年的动新闻编导拆解 AI 视频从 0 到 1 的生产流程，重点回答了两个学生最常问的问题：提示词为什么总写不对，以及长镜头为什么会跑偏。",
    "takeaway": "这篇把我们这几天攒的经验装进了一个能直接背的框架，建议给编剧和分镜各看一遍。三个最硬的观点：一是**脚本不是新闻稿，脚本更不是播音稿**——编导做的是视觉思考，要打破文字思考框，建立文字与影像的关系；二是提示词效果差，多半是因为**只说了模糊的需求，而没描述具体的画面**，他给的 C.R.E.A.T.E 公式就是四连问：有没有设定清晰角色、请求够不够具体、有没有给参考示例、输出格式明不明确；三是**输入决定输出**，提示词写得好不好，本质上反映创作者对画面的想象够不够具体。长镜头那条直接印证了第 70 期：不要强行追求超长镜头，用首尾帧控制关键画面、中间帧锁关键节点，再用动态转场把短镜头串起来；小说改视频必须先做视觉化改编，人物长什么样、在什么场景、光线如何、镜头角度是什么，越具体偏差越小。还有一条方法论值得抄：用分解思维，别指望一次对话出完美结果，先让 AI 出大纲，再逐段细化、逐步迭代。",
