    "summary": "安徽淮北一个三口之家完成了一场跨越十三年的生命接力：母亲 2013 年捐献、父亲 2019 年捐献、女儿 2026 年 11 月 12 日 24 岁时捐献，成为全国首例全家捐献造血干细胞的家庭。",
    "takeaway": "这条天然就是三段式结构，不用改编：同一个动作，三个年份，三个人——2013 母亲（淮北首位，当时公众对捐髓还有误解和恐惧）、2019 父亲（受妻子感召）、2026 女儿（成年后主动入库，接到配型通知毫不犹豫）。最该拍的是“时间”本身，把 13 年压成一条线，每次都是同一种姿势躺在采集床上，观众自己会算这笔账。两个细节别丢：他们为了顺利完成捐献，提前数月规律作息、坚持锻炼，把救人之举“当作一件需要认真对待的日常小事”；面对采访一家人都“云淡风轻”。立意可以直接用原文那句“最好的家风，是向善的传承——它藏在家人日复一日的选择里”，比任何说教都硬。提醒：这是正面报道且人物真实可查，改编须取得当事人授权，别把真实捐献者写进虚构冲突。",
