    "title": "单集成本最低500元，中专生做的AI短片海外爆火；但业内称“95%以上是亏钱的”",
    "source": "每日经济新闻 2026-11-16 16:34，新浪新闻转载；片中案例为博主“Foyege弗曳哥”的《哈利·波特》二创《爱上大难不死的男孩的女孩》",
    "url": "https://news.sina.com.cn/s/2026-11-16/doc-iniyxpxc5930517.shtml",
    "heat": "数据密集且可核：该 AI 短片单集成本 500—1600 元、YouTube/TikTok 最高播放量百万级；2026 海外微短剧市场超 60 亿美元（+67%）；前 8 个月全国上线微短剧 43 万部（去年全年 13 倍），AI 剧超九成；Seedance 2.0 成本约 1 元/秒；传统真人短剧单部 50—100 万元、AI 短剧 10—20 万元",
    "summary": "中国中专生用 AI 做的《哈利·波特》二创短片在海外出圈，单集成本仅千元级、播放量百万级，还引来歌手 JVKE 致谢和好莱坞制片人递橄榄枝；但同一篇报道里，从业者说做内容的人“95% 以上是亏钱的”。",
    "takeaway": "这篇信息量极大，建议技术和商务都看。对创作者最有用的是一条方法论：博主说为了让 AI 的表情和情感细腻，他会“设身处地站在角色的角度思考”，再把这些细节整理成提示词——这正好补上第 74 期说的“图生视频是重绘不是演”，也说明细腻度不是靠模型，是靠提示词里塞进去的“人的处境”。但真正的重点是后半段那个冷水：AI 把成本从 50—100 万压到 10—20 万、周期从月压到天，钱却没留在制作端——投流占短剧出海总成本约 50%（Meta 系 65%、Google 系 20%、TikTok 10%），今年上半年海外短剧投放素材 1961 万组同比 +324%，而内购收入增速只有 13%。案例更直白：做 10 部，运气好一部挣 20 万，总成本 60 万只回收二三十万。冷凇那句可以当结论：“未来拍摄剪辑不再是门槛，竞争焦点是谁能讲好故事。”另外合规要注意：9 月 1 日起 AI 微短剧必须在每集明显位置加提示标识。",
