    "summary": "一个年级前三十、从不告状的 14 岁“乖孩子”突然不肯上学，把自己关在房里近 17 天，砸门报警都没用；指导师用半盒橘子硬糖敲开门，孩子第一句话是“我爸妈从来不听我说话”。",
    "takeaway": "这是本期最像剧本的一篇，几乎可以直接改成短片。可拍的实物链条非常完整：楼道里攥皱的同步习题册、反锁的门、门缝里伸出的半盒橘子硬糖、大半年磨出水泡却不敢说的 40 码球鞋、半学期创可贴、楼下的三花流浪猫。家长那两句台词是全片的病灶——“我们当年下乡插秧干到十二点都没喊累，你这点作业算什么”“你不惹人家人家怎么会针对你”。干预方法也具体到能拍：每周一个晚上、饭后 20 分钟“废话时间”，孩子是唯一发言人，父母只能点头、不能插嘴不能讲大道理；三周后孩子才敢说出鞋码的事。结尾那句可以直接当片尾字幕：“你家给孩子留的那个能放开说话的位置，到底在哪呢？”提醒：这是专栏体叙述，事件为作者自述转述、未经独立核实，且明显在为申佩佩背书，有软文嫌疑，建议只取结构和细节，别当新闻事实引用。",
