    "summary": "杭州 50 岁父亲为陪读高三儿子，住进学校对面快捷酒店隔出的陪读单间：没电视没衣柜，只有空调和烧水壶，通勤从一小时变四小时，两周瘦四斤，一家人很难凑齐一桌晚饭。",
    "takeaway": "这是近期写陪读最好的一篇，细节密度极高：酒店房间是“隔出来的标准间”、第一夜翻身把床脚压断了、他自嘲成了“一只候鸟”、陪读小半年“一家人很难凑齐一桌晚饭”。最该拍的是那个反转——床塌那晚，儿子说“爸你睡我这”，作者说以前儿子不太会说这样的话；还有小女儿回家主动做作业、妈妈没到家就自己点外卖。这两个变化是全片唯一的“值不值”的答案。专家的两句话可以直接当对立面：熊丙奇说陪读会不自觉把焦虑传给孩子，蒋莉说“这一步没走完，集体生活里一点寻常的摩擦，就可能被放大成非搬出去不可的理由”。结尾那句定调极准：“好的陪伴，最终应该让孩子不再需要陪伴。”提醒：受访者用了化名，改编时也别指认具体学校。",
