    "summary": "作者用 ChatGPT 写剧本、在即梦短剧画布里完整跑通一部 30 秒 6 镜的穿越短剧，剧本、角色、场景和每一镜的提示词全部贴出来，可直接复制。",
    "takeaway": "这是云端路线的实操版，和第 80 期的本地工作流正好配成一对。最有价值的是它把“专业团队怎么做”讲透了：角色一致性要备齐三样——三视图定妆照、一段固定外貌描述、一个固定配音音色，后面所有镜头照着它来；并且坚持首帧优先，先定人物长什么样、站哪里、背景是什么，视频模型只负责让它动。几条血泪经验：一是抽卡成本，《持械入宋》普通镜头平均生成 3 次才能用、战争场面 10 次以上，《持械入宋》本身算力投入超百万，而作者第一次做就花掉 2000 多积分；二是千万别在后面改前面的，前面一改后面所有关联画面都得跟着改，钱就是这么烧掉的；三是前后有依赖的镜头要按顺序做——第 05 镜要等第 04 镜末尾的手部动作抽帧出来才能生成；四是即梦自带剪辑很弱，导出到剪映再做。它那句“工具大家都能用，最后拉开差距的还是故事和这些细节”，可以当结论。",
