    "summary": "同一句提示词在 Kling 4.0 和 Seedance 2.5 上各跑一轮、共三轮（运动跟拍、参考图人物一致性、对白与环境声），两边各跑一次不挑片，按场景给结论而不是排总分。",
    "takeaway": "这篇顺便把第 76 期的版本疑问解开了：Kling 4.0 是快手 10 月 15 日发布的新一代模型，所以“可灵 Video 2.6”那篇大概率是旧版本，采用前应以 4.0 为准。三个可直接用的发现：一是“模型只会剪”或“模型只拍长镜”都不成立，两个模型都会自己决定切不切，所以想要一镜到底必须在提示词里明写 one continuous shot；二是人物一致性上 Kling 4.0 明显更强，参考图最后一帧几乎就是本人，Seedance 2.5 认得出同类但发色变深、脸型变窄，反差是可灵让她头发不湿、Seedance 让她真的淋透了——所以“像不像”和“演得对不对”是两件事，得分开验收；三是输入能力差很多，Kling 最多 10 张参考图＋1 段参考视频且声音无开关，Seedance 最多 30 张图＋10 段视频＋10 段音频且声音可关，还多一档 480p 草稿。注意这是平台自有博客，有导流倾向，结论只当参考。",
