    "takeaway": "这是目前看到最诚实的一篇实战复盘，建议全组必读，尤其那句“自动 QA 的绿灯只能证明文件没坏，不能证明片子对了”。5 类缺陷可以直接当我们的验收清单：人物下半身缺失、道具数量错（两个蜥蜴箱）、跨镜颜色漂移、口型在说另一种语言、异源镜衔接生硬。6 个根因里最关键的一条——素材是半身立绘，脚本却写“平躺沙发”，图里没有下半身，模型只能编，所以先定素材能力边界再写脚本姿态。改造方案非常可抄：分镜加 5 个可执行字段（pose_ref／prop_placement／color_lock／camera／continuity），一致性三件套（角色外观板＋道具色卡 HEX＋房间平面图），两道强制闸门。口型那条最实用——改成 audio-first，先配中文拿到真实时长再谈口型，没有唇形模型就降级为“中性开合＋字幕承载”并明说，因为“口型对不齐可以降级，但嘴在说别的语言是硬伤”。",
