    "summary": "别把整段文案直接贴进生成框，先转成一行一镜的镜头表（动作/景别/运镜/台词/旁白/预估时长），再逐镜生成、挑片、剪成一条。",
    "takeaway": "这条正好补上工作室从剧本到分镜中间的空白，而且是目前看到最可落地的一篇：一是给了“文案→镜头表”可直接复制的提示词模板（只输出 JSON、一镜一动作、人物只写 <人物A> 代号、est_dur 取“动作做完”和“念完”里较长的）；二是那张六类改法表极其好用——情绪改身体细节、形容词拆成光线环境声音、否定改拍缺席的证据、时间跨度交给旁白、因果先拍触发再拍反应、画面里的字后期合成；三是 9 项校验清单，其中“一镜一运镜”“旁白没混进画面”“分组不超 duration 范围”三条最容易翻车；两个官方依据值得记住：Seedance 明确说不要用完整剧本当提示词（过度冗余会让模型理解混乱），且精确时间点“0—3 秒”模型支持不稳定，要按镜头1/2/3 组织；旁白的取舍可直接引红果燕北那句“能通过对白表达的，绝不用画外音”。",
