    "summary": "首尾帧生视频用起点图＋终点图把运动交给模型，是目前最可控的 AI 特效做法；想做成一镜到底，就把它拆成 A→B、B→C、C→D 各生成一段再剪。",
    "takeaway": "这条直接解决了第 66 期实测里“一镜到底变成硬切”的问题：不要指望一次生成连续长镜头，拆成多段首尾帧再接，反而稳；两个反直觉的操作要点必须记住——提示词越简单越好、不要写运镜（两张图的差异本身就决定了怎么动，再写运镜反而打架），以及关掉智能分镜、时长给 5 秒即可（11 秒太多，AI 跑不动也容易变形）；案例也很实用：一粒种子到麦苗，出来就是植物生长的延时摄影，而实拍要一两个月；结尾那句值得发给全组：“AI 抬高的是‘手’的下限，‘眼’的高低反而更重要了——工具人人可用，判断力不是。”",
