    "time": "22:21",
    "title": "AI 视频中的电影级运镜：Kling、Veo、Grok Imagine 与 Seedance 的提示词指南",
    "source": "HiAPI 博客，2026-11-03",
    "url": "https://hiapi.ai/zh/blog/cinematic-camera-movements-ai-video-prompts",
    "heat": "价格可核：Kling 3.0 Turbo 720p 约 0.13 美元/秒；Seedance 2.5 图生／文生 720p 约 0.204 美元/秒、参考生视频 720p 约 0.2715 美元/秒；Grok Imagine 1.5 约 0.015 美元/秒（480p）／0.0282（720p）；Veo 3.1 720p 约 0.29 美元/秒（含音频 0.57）",
    "summary": "实测六种电影级运镜（推近、拉远、摇摄、环绕、跟拍、升降）跨四款模型的提示词写法，结论是明确写出运镜名称比任何形容词都有效。",
    "takeaway": "最好用的一句方法论：“把镜头当成一个有自己动词的角色”——推近、拉远、摇摄、环绕、跟拍、升降；实测结论可直接进我们的分镜规范：推近和环绕最可靠，甩摇和复合运动最不可靠，需要多段运动就生成两段再剪，别在一条提示词里塞多个动作；判断跟拍是否失败有个土办法——主体身后的背景该是可信的模糊，不是拖影；省钱的办法是先用最便宜的模型（Grok 约 0.015 美元/秒）迭代运镜措辞，定稿再换贵的；另一个对我们很有用的能力：Seedance 2.5 参考生视频用 @video1 可把一条现成视频的镜头运动轨迹迁移到新主体上，找到好运镜就能复用到整片。",
