    "takeaway": "最该记的是它暴露的错误类型：坏的不是画质，是“谁是谁、谁在哪里、谁与谁互动”——模型不真的理解主体关系，这对我们做家庭短片是致命的，人物关系比画面漂亮重要得多；“一镜到底变成硬切”也要预防，分镜里设计了长镜头就别指望一次生成；最有价值的是它的成本观——单次生成价格掩盖了真实成本，提示词调试、反复生成、筛选素材、失败修改、等待、人工修补都要算进去，做预算时按这个算；它给的三条验收维度可直接借用：生成稳定性、修改可控性、综合交付成本。结论一句：“好镜头吸引人，稳定交付留住人。”",
