    "takeaway": "最值得学的是它的架构思路而不是工具：五个工位各自出产物、全部存对象存储，调度层只负责状态，所以“单集返工不影响其他集、整部短剧可并行生产”——这套解耦方式可以直接搬到我们的排期上；它自己给的定位也很清楚：不是替代创作者，而是把试错成本降下来，“过去一条短片排期两周，现在验证一个想法只要半天”，正好对应我们要不要做十个不同版本的决策；两个坑它写明了：成本大头在图像与视频生成、失败重试会烧额度（所以提示词阶段多花时间），以及角色一致性要靠固定提示词＋参考图＋工作流调参，不是开箱即完美。商用前必须自行确认模型条款与素材版权。",
