    "takeaway": "这条和第 46 期的长规范互补，是能贴在墙上的短公式：运镜（镜头怎么动）＋动作（主体干什么）＋细节（微动效，让画面不僵）；缺一段的后果他讲透了——只写动作镜头是死的、只写运镜主体不知干什么、不写细节像贴图；最适合我们的是那个案例：“摄像机缓慢推进到女孩的眼睛，女孩笑着笑着就哭了，细节：随风而动的头发”——这正是家庭情绪短片要的镜头，可直接试；避坑三条也实用：纯色背景必须补头发/衣角/光影、有人说话必须开音画同步否则口型飘、单镜头记得关智能分镜。最值得记的是他那句判断：“模型越强，提示词越短，难的不再是写细，而是想准。”",
